                        auto* c9 = s.MakeConstant();
                        std::string d9 = std::to_string(val);
                        c9->VpiDecompile(d9);
                        c9->VpiSize(64);
                        c9->VpiValue("INT:" + d9);
                        c9->VpiConstType(vpiIntConst);
                        c9->VpiParent(r);
                        const syntax::SyntaxNode* anchor9 = bsyn;
                        if (auto* be9 =
                                bsyn->as_if<syntax::BinaryExpressionSyntax>())
                            anchor9 = be9->left;
