        anonMemberRefPrefix134(fts, tm, std::string(rt->VpiFullName()));
        if (((structCloneMemberRefParent || ats9CloneRefParent) &&
             fts->VpiName().empty()) ||
            memberEnumClone)
            fts->VpiParent(rt);
